const results = await Promise.all([
  tools.exec_command({
    cmd: "sed -n '1,240p' README.md",
    workdir: "/app/code",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "rg -n '^(def |class |import |from )|load|save|pickle|h5|mat|filter|smooth|bin|trial|neuron|cell|session|dff|delta' --glob '*.py' .",
    workdir: "/app/code",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  }),
  tools.exec_command({
    cmd: "wc -l *.py README.md && python3 -c 'import json, pathlib; [print(p.name, len(json.loads(p.read_text()).get(\"cells\", []))) for p in pathlib.Path(\".\").glob(\"*.ipynb\")]'",
    workdir: "/app/code",
    yield_time_ms: 10000,
    max_output_tokens: 10000
  })
]);
for (const r of results) text(r.output);

