import numpy as np,gc,sys
sys.path.insert(0,'/app'); import convert_data as c
cat,maps=c.build_catalog(); fails=[]; negative=[]
for et,entries in c.grouped(cat).items():
 b=np.load(c.BEH/f'Beh_{et}.npy',allow_pickle=True).item()
 for e in entries:
  sid=e['session_id']; beh=b[e['source_behavior_key']]; _,nfr=c.infer_shape(sid)
  trv=np.asarray(beh['ft_trInd'][:nfr]); pos=np.asarray(beh['ft_Pos'][:nfr]);
  base=np.isfinite(trv)&np.asarray(beh['ft_CorrSpc'][:nfr],bool)&(np.asarray(beh['ft_move'][:nfr])>0)
  for tr,w in enumerate(beh['WallName']):
   if str(w) not in maps[sid]:continue
   ix=np.flatnonzero(base&(trv==tr)); cls=np.floor(pos[ix]/10).astype(int)
   bad=np.flatnonzero(np.diff(cls)<0)
   if len(bad):
    fails.append((sid,tr,len(ix),cls[bad[0]],cls[bad[0]+1],pos[ix[bad[0]]],pos[ix[bad[0]+1]],ix[bad[0]],ix[bad[0]+1]))
    negative.extend(np.diff(pos[ix])[np.diff(cls)<0].tolist())
 del b;gc.collect()
print('trials with backward class transition',len(fails),'of',sum(int(e.get('has_reward',False) or True) for e in cat))
print('transitions',len(negative),'delta pos range',min(negative),max(negative),'median',np.median(negative))
for x in fails[:30]:print(x)
